// Embedded Photo Fallbacks for Dr. Saurabh Chipde Practice Portal
const DOCTOR_PHOTOS = {
  coat: "data:image/jpeg;base64,",
  scrubs: "data:image/jpeg;base64,",
  scrubsAlt: "data:image/jpeg;base64,"
};

// Immediate image resolver: if image is broken or missing on GitHub, replace with embedded photo
function resolveDoctorImages() {
  document.querySelectorAll('img').forEach(img => {
    const src = img.getAttribute('src') || '';
    if (src.includes('dr-chipde-apollo-coat')) {
      img.onerror = function() { this.onerror = null; this.src = DOCTOR_PHOTOS.coat; };
      // If already errored or broken
      if (img.naturalWidth === 0 && img.complete) {
        img.src = DOCTOR_PHOTOS.coat;
      }
    } else if (src.includes('dr-chipde-scrubs-alt')) {
      img.onerror = function() { this.onerror = null; this.src = DOCTOR_PHOTOS.scrubsAlt; };
      if (img.naturalWidth === 0 && img.complete) {
        img.src = DOCTOR_PHOTOS.scrubsAlt;
      }
    } else if (src.includes('dr-chipde-scrubs')) {
      img.onerror = function() { this.onerror = null; this.src = DOCTOR_PHOTOS.scrubs; };
      if (img.naturalWidth === 0 && img.complete) {
        img.src = DOCTOR_PHOTOS.scrubs;
      }
    }
  });
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', resolveDoctorImages);
} else {
  resolveDoctorImages();
}
window.addEventListener('load', resolveDoctorImages);